    INSERT INTO questions (module_id, lesson_id, topic_tag, question_type, question_en, options_en, correct_answer, explanation_en, difficulty, is_mock_test_eligible)
    VALUES
    (6,1,'emergency-handling','multiple_choice','What is the first thing to do at an accident scene?','["Drive away","Ensure your own safety first","Move the injured immediately","Take photos"]',1,'Ensure your own safety first. Park safely, turn on hazard lights, and assess the situation.',1,true),
    (6,1,'emergency-handling','multiple_choice','What is the FRSC emergency number?','["911","122","999","112"]',1,'The FRSC emergency number is 122. Call for road accidents.',1,true),
    (6,1,'emergency-handling','multiple_choice','What is the general emergency number in Nigeria?','["122","112","999","911"]',1,'112 is the general emergency number in Nigeria.',1,true),
    (6,1,'emergency-handling','multiple_choice','Should you move an injured person at an accident scene?','["Yes, immediately","No — unless there is immediate danger like fire","Only if they ask","Only if they are conscious"]',1,'Do not move injured persons unless there is immediate danger like fire. Movement can worsen injuries.',1,true),
    (6,1,'emergency-handling','multiple_choice','What should you do if you are first at an accident scene?','["Leave","Stop, secure the scene, call for help, provide first aid","Take photos and leave","Wait for someone else"]',1,'Stop, secure the scene with warning triangles, call emergency services, and provide first aid.',1,true),
    (6,1,'emergency-handling','multiple_choice','How far behind your vehicle should you place a warning triangle?','["5 metres","45 metres or more","10 metres","2 metres"]',1,'Place warning triangles at least 45 metres behind your vehicle to warn approaching traffic.',2,true),
    (6,1,'emergency-handling','multiple_choice','What information should you give when calling emergency services?','["Just your name","Location, number of casualties, severity of injuries, your name","Only the location","Only the number of vehicles"]',1,'Give: exact location, number of casualties, severity of injuries, and your name.',1,true),
    (6,1,'emergency-handling','multiple_choice','What should you do if a vehicle is on fire at an accident scene?','["Pour water","Use a fire extinguisher if safe, evacuate everyone, call fire service","Run away","Open the bonnet"]',1,'Use a fire extinguisher if safe, evacuate everyone to a safe distance, and call the fire service.',2,true),
    (6,1,'emergency-handling','multiple_choice','Should you give water to an injured person at an accident?','["Yes, always","No — they may need surgery and water can cause complications","Only if they are thirsty","Only if they are conscious"]',1,'Do not give water. If they need surgery, water in the stomach can cause complications.',2,true),
    (6,1,'emergency-handling','multiple_choice','What should you do if an injured person is unconscious but breathing?','["Move them","Place in recovery position, monitor breathing, do not move unless in danger","Slap their face","Pour water on them"]',1,'Place in recovery position, monitor breathing, and do not move unless in immediate danger.',2,true),
    (6,1,'emergency-handling','multiple_choice','What should you do if an injured person is not breathing?','["Nothing","Start CPR if trained, call for help","Pour water","Shake them"]',1,'If trained, start CPR immediately. If not trained, call for help and follow instructions.',2,true),
    (6,1,'emergency-handling','multiple_choice','What is the recovery position?','["Lying on the back","Lying on the side with airway open","Sitting up","Standing"]',1,'Recovery position: lying on the side with the head tilted back to keep the airway open.',2,true),
    (6,1,'emergency-handling','multiple_choice','What should you do for a bleeding wound?','["Nothing","Apply firm pressure with a clean cloth","Pour water on it","Apply a tourniquet immediately"]',1,'Apply firm, direct pressure with a clean cloth or bandage to stop bleeding.',1,true),
    (6,1,'emergency-handling','multiple_choice','When should a tourniquet be used?','["For any bleeding","Only for severe, life-threatening limb bleeding that cannot be stopped by pressure","Never","For minor cuts"]',1,'Tourniquets are a last resort for severe limb bleeding that cannot be controlled by pressure.',3,true),
    (6,1,'emergency-handling','multiple_choice','What should you do for a burn at an accident scene?','["Apply butter","Cool with running water for 20 minutes","Apply ice","Pop blisters"]',1,'Cool burns with running water for at least 20 minutes. Do not apply butter or ice.',2,true),
    (6,1,'emergency-handling','multiple_choice','What should you do if someone is in shock?','["Give them water","Keep them warm, lie them down, elevate legs if no fractures","Make them walk","Give them food"]',1,'Keep them warm, lie them down, and elevate legs if no fractures are suspected.',2,true),
    (6,1,'emergency-handling','multiple_choice','What should you do if you suspect a spinal injury?','["Move them to sit","Do not move them — support their head and neck","Turn them on their side","Make them stand"]',1,'Do not move them. Support their head and neck in the position found. Wait for paramedics.',2,true),
    (6,1,'emergency-handling','multiple_choice','What should you do if a casualty is trapped in a vehicle?','["Pull them out","Do not move them — wait for rescue services with equipment","Force doors open","Break windows"]',1,'Do not move trapped casualties. Wait for rescue services with proper extraction equipment.',2,true),
    (6,1,'emergency-handling','multiple_choice','What should you do if you witness a hit-and-run?','["Chase the driver","Note the plate number, call police, help the victim","Ignore it","Only help the victim"]',1,'Note the registration number, call police immediately, and help the victim.',2,true),
    (6,1,'emergency-handling','multiple_choice','What should you do at night at an accident scene?','["Use your headlights only","Use hazard lights, headlights, and reflective triangles","Use no lights","Use interior lights"]',1,'Use hazard lights, headlights on dipped, and place reflective triangles to warn others.',2,true),
    (6,2,'emergency-handling','multiple_choice','What should you do if your vehicle breaks down on a highway?','["Stay in the car","Turn on hazard lights, pull to the shoulder, place triangles, move behind barrier","Get out and wave for help","Walk on the road"]',1,'Turn on hazard lights, pull onto the shoulder, place reflective triangles, and move to safety behind a barrier.',1,true),
    (6,2,'emergency-handling','multiple_choice','Where is the safest place to wait after a breakdown?','["In the car","Behind a barrier or on the embankment, away from traffic","In front of the car","On the road"]',1,'Behind a barrier or on the embankment, well away from traffic. Never stand behind or in front of the car.',2,true),
    (6,2,'emergency-handling','multiple_choice','What should you do if your vehicle breaks down in a tunnel?','["Stay in the car","Turn on hazard lights, leave via nearest exit, call for help","Walk through the tunnel","Open the bonnet"]',1,'Turn on hazard lights, leave via the nearest pedestrian exit, and call tunnel control or emergency services.',3,true),
    (6,2,'emergency-handling','multiple_choice','What should you do if your vehicle breaks down on a bridge?','["Stay in the car","Turn on hazard lights, move to safety, call for help","Jump off the bridge","Walk on the road"]',1,'Turn on hazard lights, move to a safe area away from traffic, and call for help.',2,true),
    (6,2,'emergency-handling','multiple_choice','What should you do if your tyre blows out on the highway?','["Brake hard","Grip steering firmly, ease off accelerator, pull over safely","Steer sharply","Accelerate"]',1,'Grip the steering wheel firmly, ease off the accelerator, and pull over to the shoulder smoothly.',2,true),
    (6,2,'emergency-handling','multiple_choice','What should you do if your brakes fail?','["Panic","Pump the brake pedal, use handbrake gradually, use engine braking","Turn off the engine","Pull the handbrake hard"]',1,'Pump the brake pedal to build pressure, use handbrake gradually, and downshift to use engine braking.',2,true),
    (6,2,'emergency-handling','multiple_choice','What should you do if your accelerator sticks?','["Brake hard","Shift to neutral, brake gently, steer to safety, turn off engine when stopped","Turn off engine while moving","Pull handbrake"]',1,'Shift to neutral, brake gently, steer to a safe stop, then turn off the engine.',3,true),
    (6,2,'emergency-handling','multiple_choice','What should you do if your steering fails?','["Brake hard","Slow down gradually using brakes, use hazard lights, stop safely","Turn off engine","Pull handbrake"]',1,'Slow down gradually using the footbrake, turn on hazard lights, and stop safely.',3,true),
    (6,2,'emergency-handling','multiple_choice','What should you do if your headlights fail at night?','["Keep driving","Slow down, use hazard lights, stop safely","Use interior lights","Drive faster"]',1,'Slow down, use hazard lights to warn others, and stop safely. Do not continue without lights.',2,true),
    (6,2,'emergency-handling','multiple_choice','What should you do if your engine catches fire?','["Pour water","Turn off engine, get out, move away, call fire service","Open the bonnet","Drive faster"]',1,'Turn off the engine, get everyone out, move to a safe distance, and call the fire service. Do not open the bonnet.',2,true),
    (6,2,'emergency-handling','multiple_choice','Why should you not open the bonnet if the engine is on fire?','["It does not matter","Air feeds the fire and it can flare up in your face","It is too hot","The bonnet is locked"]',1,'Opening the bonnet feeds oxygen to the fire, causing it to flare up dangerously.',2,true),
    (6,2,'emergency-handling','multiple_choice','What should you do if your car starts to skid?','["Brake hard","Steer into the skid, ease off accelerator","Steer away","Accelerate"]',1,'Steer into the skid (in the direction the rear is sliding) and ease off the accelerator. Do not brake.',2,true),
    (6,2,'emergency-handling','multiple_choice','What should you do if you are in a collision?','["Drive away","Stop, check for injuries, call police and emergency if needed, exchange details","Argue with the other driver","Leave the scene"]',1,'Stop, check for injuries, call emergency services if needed, exchange details, and report to police.',1,true),
    (6,2,'emergency-handling','multiple_choice','What details should you exchange after a collision?','["Nothing","Name, address, phone, licence number, vehicle registration, insurance","Only phone number","Only name"]',1,'Exchange: full name, address, phone, licence number, vehicle registration, and insurance details.',1,true),
    (6,2,'emergency-handling','multiple_choice','When must you report a collision to the police?','["Never","If there are injuries or significant damage","Only if someone dies","Only if you are at fault"]',1,'Report to police if there are injuries, significant damage, or if the road is blocked.',1,true),
    (6,2,'emergency-handling','multiple_choice','Within what time must you report a collision to the police?','["24 hours","48 hours","72 hours","One week"]',0,'Report a collision to the police within 24 hours.',2,true),
    (6,2,'emergency-handling','multiple_choice','What should you do if you hit a parked car and the owner is not there?','["Drive away","Leave a note with your details and report to police","Wait all day","Nothing"]',1,'Leave a note with your contact and insurance details, and report to the police.',2,true),
    (6,2,'emergency-handling','multiple_choice','What should you do if you hit a pedestrian?','["Drive away","Stop, call emergency services, provide first aid, stay at the scene","Move them to the side","Leave to get help"]',1,'Stop immediately, call 122 and 112, provide first aid if trained, and stay at the scene.',1,true),
    (6,2,'emergency-handling','multiple_choice','What should you do if you hit an animal?','["Drive away","Stop, check if it needs help, report if livestock","Move it off the road","Nothing"]',1,'Stop if safe. Check if the animal needs help. If livestock, report to the owner or police.',2,true),
    (6,2,'emergency-handling','multiple_choice','What should you do if your vehicle is submerged in water?','["Wait for help","Open or break a window immediately, get out","Call for help first","Stay in the car"]',1,'Open or break a side window immediately before the car sinks. Get out quickly.',3,true),
    (6,2,'emergency-handling','multiple_choice','What is the best tool to break a car window?','["Your fist","A window breaker tool or the metal headrest post","Your phone","A water bottle"]',1,'A window breaker tool is best. The metal posts of a headrest can also work.',3,true),
    (6,2,'emergency-handling','multiple_choice','Which window is easiest to break in an emergency?','["Windshield","Side window — tempered glass","Rear window","Sunroof"]',1,'Side windows are tempered glass and easier to break than the laminated windshield.',3,true),
    (6,2,'emergency-handling','multiple_choice','What should you do if your car is on fire and you cannot get out?','["Wait","Break a window with any available object","Call for help and wait","Lie down"]',1,'Break a window immediately using any hard object. Get out as fast as possible.',3,true),
    (6,2,'emergency-handling','multiple_choice','What should you do if you smell petrol/gas inside the car?','["Ignore it","Stop safely, turn off engine, do not smoke, check for leaks","Light a match to check","Keep driving"]',1,'Stop safely, turn off the engine, do not use any flames, and check for fuel leaks.',2,true),
    (6,2,'emergency-handling','multiple_choice','What should you do if your car starts to roll backwards on a hill?','["Jump out","Apply handbrake and footbrake, shift to first gear or park","Steer into the hill","Accelerate"]',1,'Apply handbrake and footbrake firmly. Shift to first gear (manual) or park (automatic).',2,true),
    (6,2,'emergency-handling','multiple_choice','What should you do if you get lost while driving?','["Keep driving randomly","Pull over safely, check your map or GPS","Speed up","Ask a stranger while driving"]',1,'Pull over safely to check directions. Do not use your phone while driving.',1,true),
    (6,2,'emergency-handling','multiple_choice','What should you do if you are being followed by a suspicious vehicle?','["Drive home","Drive to a police station or busy public place","Speed up","Stop and confront them"]',1,'Drive to the nearest police station or a busy, well-lit public place. Do not go home.',2,true),
    (6,2,'emergency-handling','multiple_choice','What should you do if your car is overheating on a highway?','["Keep driving","Stop safely, turn off engine, wait for it to cool","Open the radiator cap","Pour cold water on the engine"]',1,'Stop safely, turn off the engine, and wait for it to cool. Never open the radiator cap when hot.',2,true),
    (6,3,'emergency-handling','multiple_choice','What is the first step in CPR?','["Give breaths","Check responsiveness and call for help","Start compressions","Check pulse"]',1,'Check responsiveness, call for help, then begin chest compressions if trained.',2,true),
    (6,3,'emergency-handling','multiple_choice','What is the correct CPR compression rate?','["60 per minute","100-120 per minute","80 per minute","40 per minute"]',1,'CPR compression rate is 100-120 per minute. Push hard and fast in the centre of the chest.',3,true),
    (6,3,'emergency-handling','multiple_choice','What is the correct CPR compression depth for adults?','["2 cm","5-6 cm","10 cm","1 cm"]',1,'Push down 5-6 cm for adults at 100-120 compressions per minute.',3,true),
    (6,3,'emergency-handling','multiple_choice','How many compressions to breaths in standard CPR?','["15:2","30:2","10:2","5:1"]',1,'30 compressions followed by 2 rescue breaths for standard CPR.',3,true),
    (6,3,'emergency-handling','multiple_choice','What is hands-only CPR?','["No compressions","Continuous compressions without rescue breaths","Just touching","No CPR"]',1,'Hands-only CPR is continuous chest compressions without rescue breaths. Better than nothing.',3,true),
    (6,3,'emergency-handling','multiple_choice','What should you do for a choking person who is conscious?','["Pat their back","Give 5 back blows then 5 abdominal thrusts (Heimlich)","Give water","Slap their face"]',1,'Give 5 back blows between the shoulder blades, then 5 abdominal thrusts (Heimlich manoeuvre).',2,true),
    (6,3,'emergency-handling','multiple_choice','What should you do if a choking person becomes unconscious?','["Nothing","Start CPR and call for help","Pour water","Shake them"]',1,'If a choking person becomes unconscious, start CPR and call emergency services immediately.',3,true),
    (6,3,'emergency-handling','multiple_choice','What is the Heimlich manoeuvre?','["A type of bandage","Abdominal thrusts to clear an airway blockage","A CPR technique","A recovery position"]',1,'The Heimlich manoeuvre uses abdominal thrusts to dislodge an object blocking the airway.',2,true),
    (6,3,'emergency-handling','multiple_choice','What should you do for a minor cut?','["Ignore it","Clean with water, apply antiseptic and a plaster","Pour alcohol","Wrap tightly"]',1,'Clean with water, apply antiseptic, and cover with a plaster or bandage.',1,true),
    (6,3,'emergency-handling','multiple_choice','What should you do for a deep wound?','["Clean and bandage","Apply firm pressure, elevate if possible, seek medical help","Pour water","Apply a tourniquet"]',1,'Apply firm pressure with a clean dressing, elevate if possible, and seek medical help.',2,true),
    (6,3,'emergency-handling','multiple_choice','What should you do for a nosebleed?','["Tilt head back","Sit upright, lean forward, pinch the soft part of the nose","Lie down","Tilt head to the side"]',1,'Sit upright, lean forward slightly, and pinch the soft part of the nose for 10-15 minutes.',1,true),
    (6,3,'emergency-handling','multiple_choice','What should you do for a sprain?','["Apply heat","RICE: Rest, Ice, Compression, Elevation","Massage it","Walk it off"]',1,'RICE: Rest, Ice, Compression, Elevation. Apply ice for 15-20 minutes.',1,true),
    (6,3,'emergency-handling','multiple_choice','What should you do for a suspected fracture?','["Move the limb","Immobilise the area, do not move the person, call for help","Apply heat","Try to set the bone"]',1,'Immobilise the area, do not move the person unnecessarily, and call for emergency help.',2,true),
    (6,3,'emergency-handling','multiple_choice','What should you do for a head injury?','["Ignore it","Monitor for symptoms, seek medical help if confused or unconscious","Give water","Let them sleep"]',1,'Monitor closely. Seek immediate medical help if the person is confused, unconscious, or vomiting.',2,true),
    (6,3,'emergency-handling','multiple_choice','What are signs of a serious head injury?','["Nothing","Unconsciousness, confusion, vomiting, severe headache, seizure","Mild headache","Slight dizziness only"]',1,'Signs: unconsciousness, confusion, vomiting, severe headache, seizure, or clear fluid from ears.',2,true),
    (6,3,'emergency-handling','multiple_choice','What should you do if someone is having a seizure?','["Hold them down","Clear the area, protect their head, do not put anything in their mouth","Put a spoon in their mouth","Pour water on them"]',1,'Clear the area of objects, protect their head with something soft, and do not put anything in their mouth.',2,true),
    (6,3,'emergency-handling','multiple_choice','What should you do after a seizure stops?','["Stand them up","Place in recovery position, monitor breathing","Give water","Let them drive"]',1,'Place in recovery position, monitor breathing, and stay with them until fully alert.',2,true),
    (6,3,'emergency-handling','multiple_choice','What should you do for a heat stroke victim?','["Give them hot tea","Move to shade, cool with water, fan them, call for help","Wrap them in blankets","Give them exercise"]',1,'Move to a cool shaded area, cool with water, fan them, and call emergency services.',2,true),
    (6,3,'emergency-handling','multiple_choice','What are signs of heat stroke?','["Normal temperature","High body temperature, confusion, hot dry skin, rapid pulse","Shivering","Cold sweat"]',1,'Signs: high body temperature, confusion, hot dry skin, rapid pulse, and possible unconsciousness.',2,true),
    (6,3,'emergency-handling','multiple_choice','What should you do for someone in hypoglycaemic shock (low blood sugar)?','["Give them insulin","Give them fast-acting sugar like glucose tablets or juice","Give them water","Let them rest"]',1,'Give fast-acting sugar: glucose tablets, fruit juice, or sugary drinks. If unconscious, do not give anything by mouth.',2,true),
    (6,3,'emergency-handling','multiple_choice','What should you do for a heart attack victim?','["Let them drive to hospital","Call emergency services, help them sit, loosen clothing, give aspirin if available","Make them lie flat","Give them water"]',1,'Call emergency services, help them sit comfortably, loosen tight clothing, and give aspirin if available and not allergic.',3,true),
    (6,3,'emergency-handling','multiple_choice','What are signs of a heart attack?','["Nothing","Chest pain, shortness of breath, nausea, pain in arm or jaw","Headache","Stomach ache only"]',1,'Signs: chest pain or pressure, shortness of breath, nausea, pain radiating to arm or jaw, sweating.',3,true),
    (6,3,'emergency-handling','multiple_choice','What should you do for a stroke victim?','["Wait to see if it passes","Call emergency services immediately — time is critical","Give them water","Make them exercise"]',1,'Call emergency services immediately. Every minute counts. Do not give food or water.',3,true),
    (6,3,'emergency-handling','multiple_choice','What is the FAST test for stroke?','["A driving test","Face, Arms, Speech, Time","First Aid Safety Test","Fast Action Stroke Test"]',1,'FAST: Face (drooping), Arms (cannot raise), Speech (slurred), Time (call emergency immediately).',3,true),
    (6,3,'emergency-handling','multiple_choice','What should you do for an electric shock victim?','["Touch them","Turn off the power source first, then check breathing","Pour water","Move them with bare hands"]',1,'Turn off the power source first. Do not touch them until the power is off. Then check breathing and call for help.',3,true),
    (6,3,'emergency-handling','multiple_choice','What should you do for a drowning victim?','["Give mouth-to-mouth in the water","Get them out of water, check breathing, start CPR if needed","Push on their stomach","Hold them upside down"]',1,'Get them out of the water, check breathing, and start CPR if not breathing. Call for help.',2,true),
    (6,3,'emergency-handling','multiple_choice','What should you do for an insect sting?','["Ignore it","Remove the sting, wash with soap and water, apply cold compress","Squeeze the area","Apply heat"]',1,'Remove the sting, wash with soap and water, and apply a cold compress to reduce swelling.',1,true),
    (6,3,'emergency-handling','multiple_choice','What should you do for a snake bite?','["Suck out the venom","Keep the person still and calm, immobilise the limb, call for help","Apply a tourniquet","Cut the wound"]',1,'Keep the person still and calm, immobilise the bitten limb, and call for emergency help immediately.',3,true),
    (6,3,'emergency-handling','multiple_choice','What should you NOT do for a snake bite?','["Call for help","Cut the wound, suck the venom, or apply a tourniquet","Keep them calm","Immobilise the limb"]',1,'Do not cut the wound, suck the venom, or apply a tourniquet. These are outdated and dangerous.',3,true),
    (6,3,'emergency-handling','multiple_choice','What should you do for a dog bite?','["Ignore it","Wash with soap and water, apply pressure to stop bleeding, seek medical help","Squeeze the wound","Apply a tourniquet"]',1,'Wash with soap and water, apply pressure to stop bleeding, and seek medical help for rabies risk.',2,true),
    (6,3,'emergency-handling','multiple_choice','What should you do for a foreign object in the eye?','["Rub the eye","Do not rub, rinse with clean water, seek medical help if not removed","Remove with fingers","Apply pressure"]',1,'Do not rub. Rinse with clean water. If it does not wash out, seek medical help.',1,true),
    (6,3,'emergency-handling','multiple_choice','What should you do for a chemical splash in the eye?','["Rub the eye","Rinse with clean water for at least 15 minutes, call for help","Cover the eye","Apply a cold compress"]',1,'Rinse with clean water for at least 15 minutes, then seek immediate medical help.',2,true),
    (6,3,'emergency-handling','multiple_choice','What should you do for a knocked-out tooth?','["Throw it away","Rinse gently, place back in socket or in milk, see a dentist immediately","Wrap in tissue","Put in water"]',1,'Rinse gently, try to place back in the socket, or store in milk. See a dentist immediately.',2,true),
    (6,3,'emergency-handling','multiple_choice','What should you do for a severe allergic reaction (anaphylaxis)?','["Wait and see","Call emergency services, use an EpiPen if available, keep them calm","Give them water","Make them lie flat without elevating legs"]',1,'Call emergency services immediately. Use an EpiPen if available. Keep them calm and monitor breathing.',3,true),
    (6,3,'emergency-handling','multiple_choice','What are signs of anaphylaxis?','["Mild itching","Swelling of face/throat, difficulty breathing, rapid pulse, dizziness","Slight rash","Runny nose"]',1,'Signs: swelling of face and throat, difficulty breathing, rapid pulse, dizziness, and collapse.',3,true),
    (6,3,'emergency-handling','multiple_choice','What should you do for a fainting person?','["Slap their face","Lie them down, elevate legs, loosen tight clothing","Pour water on them","Make them stand"]',1,'Lie them down, elevate their legs, loosen tight clothing, and ensure fresh air.',1,true),
    (6,3,'emergency-handling','multiple_choice','What should you do if someone is hyperventilating?','["Give them a paper bag","Help them breathe slowly and calmly","Tell them to breathe faster","Ignore them"]',1,'Help them breathe slowly and calmly. Reassure them. Do not use a paper bag unless advised by a professional.',2,true),
    (6,3,'emergency-handling','multiple_choice','What should you do for a pregnant woman in distress?','["Wait","Call emergency services, help her sit comfortably, follow instructions","Make her walk","Give her food"]',1,'Call emergency services, help her sit or lie comfortably, and follow the operator instructions.',2,true),
    (6,3,'emergency-handling','multiple_choice','What should you do for a person in a diabetic emergency who is unconscious?','["Give them sugar by mouth","Do not give anything by mouth, place in recovery position, call for help","Start CPR","Give them insulin"]',1,'Do not give anything by mouth. Place in recovery position and call emergency services immediately.',3,true),
    (6,3,'emergency-handling','multiple_choice','What should you do for a person having an asthma attack?','["Tell them to lie down","Help them sit upright, help them use their inhaler, call for help if severe","Make them exercise","Give them water"]',1,'Help them sit upright, assist with their inhaler, and call emergency services if it does not improve.',2,true),
    (6,3,'emergency-handling','multiple_choice','What should you do for a person with a dislocated joint?','["Try to push it back","Immobilise the joint, do not try to reduce it, seek medical help","Move the joint","Apply heat"]',1,'Immobilise the joint in the position found. Do not try to push it back. Seek medical help.',3,true),
    (6,3,'emergency-handling','multiple_choice','What should you do for a person with a concussion?','["Let them sleep","Monitor closely, seek medical help, do not let them drive","Give them painkillers","Make them exercise"]',1,'Monitor closely, seek medical help, and do not let them drive or drink alcohol.',2,true),
    (6,3,'emergency-handling','multiple_choice','What should you do for a person with a puncture wound?','["Ignore it","Do not remove the object, apply pressure around it, call for help","Remove the object","Pour water into it"]',1,'Do not remove the embedded object. Apply pressure around it and call for emergency help.',3,true),
    (6,3,'emergency-handling','multiple_choice','What should you do for a person with a crush injury?','["Move the crushing object if safe","Do not move the object if it may cause more damage, call for help","Pull them out","Pour water"]',1,'If safe, remove the crushing object. If not, call for emergency services immediately. Monitor for crush syndrome.',3,true),
    (6,3,'emergency-handling','multiple_choice','What is crush syndrome?','["Nothing serious","Toxins released from crushed muscle can cause kidney failure when pressure is released","A type of fracture","A bruise"]',1,'Crush syndrome: when pressure is released from a crushed limb, toxins flood the body and can cause kidney failure.',3,true),
    (6,3,'emergency-handling','multiple_choice','What should you do for a person exposed to carbon monoxide?','["Nothing","Move to fresh air immediately, call emergency services","Give them water","Let them rest"]',1,'Move to fresh air immediately and call emergency services. Carbon monoxide is deadly.',3,true),
    (6,3,'emergency-handling','multiple_choice','What are signs of carbon monoxide poisoning?','["Nothing","Headache, dizziness, nausea, confusion, loss of consciousness","Cough","Sore throat"]',1,'Signs: headache, dizziness, nausea, confusion, and loss of consciousness. Get to fresh air immediately.',3,true),
    (6,3,'emergency-handling','multiple_choice','What should you keep in a vehicle first aid kit?','["Only bandages","Plasters, bandages, antiseptic, scissors, gloves, triangular bandage, safety pins","Only painkillers","Water only"]',1,'A first aid kit should include plasters, bandages, antiseptic wipes, scissors, gloves, and triangular bandages.',1,true),
    (6,3,'emergency-handling','multiple_choice','What should you do if you arrive at a multi-vehicle accident?','["Drive through","Stop safely, call emergency services, help if you can, do not block the road","Take photos and leave","Wait in your car"]',1,'Stop safely, call emergency services with details, help if you are able, and do not block the road for emergency vehicles.',2,true),
    (6,3,'emergency-handling','multiple_choice','What is the most important thing at any emergency scene?','["Taking photos","Safety of yourself and others","Getting there fast","Being a hero"]',1,'Your safety and the safety of others is the most important priority at any emergency scene.',1,true),
    (6,3,'emergency-handling','multiple_choice','What should you do if you are involved in a minor accident with no injuries?','["Drive away","Move vehicles to the side if safe, exchange details, take photos","Leave vehicles in the road","Argue with the other driver"]',1,'Move vehicles to the side of the road if safe, exchange details, and take photos for insurance.',1,true),
    (6,3,'emergency-handling','multiple_choice','What should you do if you see an accident and no one has stopped?','["Keep driving","Stop, secure the scene, call 122 and 112, provide first aid","Call someone else","Take photos and post online"]',1,'Stop, secure the scene with triangles, call 122 and 112, and provide first aid if trained.',1,true),
    (6,3,'emergency-handling','multiple_choice','What is the golden rule of first aid?','["Always move the casualty","Do no further harm","Give them water","Make them comfortable only"]',1,'Do no further harm. Only intervene if you know what to do, and always prioritise professional help.',1,true),
    (6,3,'emergency-handling','multiple_choice','What should you do if you are not trained in first aid at an accident?','["Leave","Call emergency services and follow their instructions","Try anyway","Take over from others"]',1,'Call emergency services and follow their phone instructions. They will guide you step by step.',1,true),
    (6,3,'emergency-handling','multiple_choice','What is the most common cause of death in road accidents?','["Bleeding","Head injuries and internal bleeding","Broken bones","Shock"]',1,'Head injuries and internal bleeding are the most common causes of death in road accidents.',2,true),
    (6,3,'emergency-handling','multiple_choice','What can significantly improve survival after a road accident?','["Nothing","Quick emergency response and bystander first aid","Waiting for police","Driving faster to hospital"]',1,'Quick emergency response and bystander first aid can dramatically improve survival rates.',1,true);
